import json,re
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
B='http://localhost:3002';a=next(a for a in json.loads(Path('.tmp-check/workspace-accounts.json').read_text(encoding='utf-8'))['accounts'] if a['key']=='navigation');expect.set_options(timeout=30000)
with sync_playwright() as p:
 browser=p.chromium.launch();c=browser.new_context(base_url=B,viewport={'width':1440,'height':1000},extra_http_headers={'Origin':B});assert c.request.post('/api/workspace/login',data={'email':a['email'],'password':a['password']}).ok;r=c.request.get('/api/workspace/store-map');assert r.ok;d=r.json();valid=[s for s in d['stores'] if s['gps_latitude'] is not None and s['gps_longitude'] is not None];print('Visible stores',len(d['stores']),'coordinate pairs',len(valid),flush=True)
 page=c.new_page();google_errors=[];page.on('console',lambda m: google_errors.extend(re.findall(r'Google Maps JavaScript API error: ([A-Za-z0-9]+)',m.text)));page.goto('/workspace/index.html');page.locator('.sidebar').hover();page.locator('.nav-search input').fill('門市管理');page.locator('.module-trigger').first.hover();page.get_by_role('navigation').get_by_role('button',name='門市管理 新版',exact=True).click();panel=page.locator('[role=tabpanel]:visible');panel.get_by_role('button',name='門市整合地圖',exact=True).click();panel=page.locator('[role=tabpanel]:visible');expect(panel.get_by_role('heading',name='門市整合地圖')).to_be_visible();expect(panel.locator('.map-store').first).to_be_visible();expect(panel.get_by_text('載入 Google 地圖…',exact=True)).to_have_count(0,timeout=45000);page.wait_for_timeout(8000);page.screenshot(path='.tmp-check/store-map-real-desktop.png');print('Google error codes:',google_errors,flush=True);print('Map alerts:',panel.locator('.map-message [role=alert]').all_text_contents(),flush=True);print('Google rendered roots:',panel.locator('.gm-style').count(),flush=True)
 assert panel.locator('.map-message [role=alert]').count()==0,'Google map reported an error';expect(panel.locator('.gm-style').first).to_be_visible();panel.locator('.map-store').first.click();expect(panel.get_by_role('region',name='選取門市資訊')).to_be_visible();expect(panel.get_by_role('link',name='在 Google Maps 開啟')).to_have_attribute('target','_blank');panel.get_by_label('搜尋門市位置').fill(valid[0]['store_code']);expect(panel.locator('.map-store')).to_have_count(1);page.set_viewport_size({'width':390,'height':844});page.screenshot(path='.tmp-check/store-map-real-mobile.png');assert page.evaluate('document.documentElement.scrollWidth <= innerWidth');print('PASS real Google map, list focus/details/external link/search and mobile layout',flush=True);browser.close()
